def comps(g,val):
    H=len(g);W=len(g[0]);seen=set();res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                st=[(i,j)];seen.add((i,j));cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            na,nb=a+da,b+db
                            if 0<=na<H and 0<=nb<W and g[na][nb]==val and (na,nb) not in seen:
                                seen.add((na,nb));st.append((na,nb))
                res.append(cells)
    return res
